				}
				tripReq := func() (interface{}, error) { return nil, identityErr }
				var counts func() gb.Counts
				var state func() gb.State
				var complete func()
				if direct {
					b := gb.NewCircuitBreaker(st)
					counts, state = b.Counts, b.State
					if tc.from == gb.StateHalfOpen { _, _ = b.Execute(tripReq); time.Sleep(2 * identityWindow); identityState(t, state(), tc.from) }
					complete = func() {
						_, _ = b.Execute(func() (interface{}, error) {
							if tc.success { return nil, nil }
							return tripReq()
						})
					}
				} else {
					b := gb.NewTwoStepCircuitBreaker(st)
					counts, state = b.Counts, b.State
					if tc.from == gb.StateHalfOpen { identityAllow(t, b)(false); time.Sleep(2 * identityWindow); identityState(t, state(), tc.from) }
					done := identityAllow(t, b)
					complete = func() { done(tc.success) }
				}
				armed = true
				if got := identityPanic(t, complete); got != "transition" { t.Fatalf("panic: %v", got) }
				identityCounts(t, counts(), gb.Counts{})
				identityState(t, state(), tc.to)
